        "Earth": 3,
        "Mars": 4,
        "Jupiter": 5,
        "Saturn": 6,
        "Uranus": 7,
        "Neptune": 8
    }

    planets = list(planets_order.keys())

    if planet1 not in planets or planet2 not in planets:
        return ()

    start = min(planets_order[planet1], planets_order[planet2])
    end = max(planets_order[planet1], planets_order[planet2])

