        return "Error: Length of operator list should be one less than the length of operand list"

    if len(operand) < 2:
        return "Error: Operand list should have at least two operands"

    for op in operator:
        if op not in ['+', '-', '*', '//', '**']:
            return "Error: Invalid operator found in the operator list"

    expression = ''
    for i in range(len(operator)):
        expression += str(operand[i]) + operator[i]
    expression += str(operand[-1])

    try:
        result = eval(expression)
        return result
    except Exception as e:
        return "Error: Invalid expression"

